import fs from 'node:fs';import {createRequire} from 'node:module';
const require=createRequire('/home/node/.openclaw/workspace/kubeclaw-pr13-recovery/package.json');
const {chromium}=require('playwright');const {default:AxeBuilder}=await import(require.resolve('@axe-core/playwright'));
const base='http://127.0.0.1:8765',out='/home/node/.openclaw/workspace/tmp/pr13-graph-closeout-20261021';
const browser=await chromium.launch({headless:true,args:['--no-sandbox']});const findings=[];const observations=[];
try{
for(const width of [1440,768,320]){
 const runContext=await browser.newContext({viewport:{width,height:1000}});const page=await runContext.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 for(const route of ['/README.html','/use/quickstart.html','/extend/first-plugin.html','/search.html']){
 const response=await page.goto(base+route);if(response.status()!==200)throw Error('HTTP '+response.status());await page.waitForLoadState('networkidle');const styled=await page.evaluate(()=>getComputedStyle(document.querySelector('main')).paddingLeft!=='0px');if(!styled)throw Error('CSS not loaded');
 const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);const axe=await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21aa']).analyze();
 if(overflow||axe.violations.length||errors.length)findings.push({width,route,overflow,violations:axe.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.slice(0,3).map(n=>n.target)})),errors});
 observations.push({width,route,status:200,overflow,axeViolations:axe.violations.length});
 if(route==='/use/quickstart.html')await page.screenshot({path:out+'/reader-'+width+'.png',fullPage:false});
 }
 await page.goto(base+'/search.html');await page.getByLabel('Words or exact identifier').fill('minimumLinePercent');await page.getByRole('button',{name:'Search',exact:true}).click();await page.waitForFunction(()=>/pages found|No results|could not/.test(document.getElementById('search-status').textContent),{timeout:30000});
 const status=await page.locator('#search-status').innerText();if(!status.includes('pages found'))findings.push({width,search:status});
 observations.push({width,search:status});await page.getByLabel('Words or exact identifier').fill('NO_SUCH_DOC_VALUE_0e19');await page.getByRole('button',{name:'Search',exact:true}).click();await page.waitForFunction(()=>document.getElementById('search-status').textContent.startsWith('No results.'));
 await runContext.close();
}
const context=await browser.newContext({javaScriptEnabled:false,viewport:{width:320,height:800}});const page=await context.newPage();await page.goto(base+'/README.html');await page.keyboard.press('Tab');const skip=await page.locator(':focus').innerText();if(skip!=='Skip to content')findings.push({keyboard:skip});await page.keyboard.press('Enter');if(await page.locator(':focus').getAttribute('id')!=='main')findings.push({skipFocus:'main not focused'});await page.locator('article').getByRole('link',{name:'Operator Quickstart',exact:true}).click();if(!page.url().endsWith('/use/quickstart.html'))findings.push({noJSNavigation:page.url()});observations.push({noJavaScriptNavigation:'PASS',skipKeyboard:'PASS'});
await context.close();
}finally{await browser.close();fs.writeFileSync(out+'/reader-browser-qa.json',JSON.stringify({observations,findings},null,2)+'\n');}
if(findings.length)process.exitCode=1;
